import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static int minutes(String s) {
        int colon = s.indexOf(':');
        return Integer.parseInt(s.substring(0, colon)) * 60 + Integer.parseInt(s.substring(colon + 1));
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[] times = new int[n];
        for (int i = 0; i < n; i++) times[i] = minutes(next());
        int now = minutes(next()), latest = -1;
        for (int t : times)
            if (t < now) latest = Math.max(latest, t);
        System.out.println(latest >= 0 ? now - latest : -1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func minutes(s string) int {
	h, m, _ := strings.Cut(s, ":")
	hh, _ := strconv.Atoi(h)
	mm, _ := strconv.Atoi(m)
	return hh*60 + mm
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	times := make([]int, n)
	for i := range times {
		times[i] = minutes(next())
	}
	now, latest := minutes(next()), -1
	for _, t := range times {
		if t < now {
			latest = max(latest, t)
		}
	}
	if latest >= 0 {
		fmt.Println(now - latest)
	} else {
		fmt.Println(-1)
	}
}
